package ru.main.explorer;
import android.app.*;import android.content.*;import android.database.MatrixCursor;import android.graphics.*;import android.widget.ListView;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PhotoSelectionTest {
 Store.Photo photo(long id,double lon){MatrixCursor c=new MatrixCursor(new String[]{"id","lat","lon","acc","path","note","created"});c.addRow(new Object[]{id,0,lon,5,"missing.jpg","Заметка "+id,1000});c.moveToFirst();Store.Photo p=new Store.Photo(c);c.close();return p;}
 ArrayList<Store.Photo> photos(Store.Photo... p){return new ArrayList<>(Arrays.asList(p));}
 @Test public void overlappingChainIncludesEveryPhotoAndSeparatePointStaysSeparate(){ArrayList<Store.Photo> ps=photos(photo(3,0),photo(2,0),photo(1,0),photo(4,0));ArrayList<PhotoGroups.Group> groups=PhotoGroups.build(ps,new float[]{0,49,98,200},new float[]{0,0,0,0},50);assertEquals(2,groups.size());assertEquals(3,groups.get(0).photos.size());assertEquals(1,groups.get(1).photos.size());assertEquals(3,groups.get(0).photos.get(0).id);}
 @Test public void identicalLocationsProduceSeparateCalloutsAndAllIdsAtAnchor(){MapView map=new MapView(RuntimeEnvironment.getApplication());map.online=false;try{map.layout(0,0,512,512);map.cx=128;map.cy=128;map.zoom=16;map.setPhotos(photos(photo(3,0),photo(2,0),photo(1,0)));assertEquals(3,map.photoGroups().size());ArrayList<Long> ids=new ArrayList<>();map.setPhotoTapListener(items->{for(Store.Photo p:items)ids.add(p.id);});Bitmap bitmap=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);map.drawPhotos(new Canvas(bitmap));assertTrue(map.tapPhotos(256,256));assertEquals(Arrays.asList(1L,2L,3L),ids);assertFalse(map.tapPhotos(30,30));}finally{map.close();}}
 @Test public void zoomPreservesSeparatePhotosAndInvalidatesLayout(){MapView map=new MapView(RuntimeEnvironment.getApplication());map.online=false;try{map.layout(0,0,512,512);map.cx=128;map.cy=128;map.zoom=12;map.setPhotos(photos(photo(1,0),photo(2,.001)));assertEquals(2,map.photoGroups().size());map.changeZoom(6);assertEquals(2,map.photoGroups().size());map.setPhotos(photos(photo(3,0)));assertEquals(1,map.photoGroups().get(0).photos.size());assertEquals(3,map.photoGroups().get(0).photos.get(0).id);}finally{map.close();}}
 @Test public void offscreenPhotosKeepVisibleSeparateMarkers(){MapView map=new MapView(RuntimeEnvironment.getApplication());map.online=false;try{map.layout(0,0,512,512);map.cx=128;map.cy=128;map.zoom=16;ArrayList<Store.Photo> ps=new ArrayList<>();for(int i=0;i<5;i++)ps.add(photo(i+1,(-80+i*40-256)*360.0/(256*(1<<16))));map.setPhotos(ps);PhotoGroups.Group group=map.photoGroups().get(0);assertEquals(3,map.photoGroups().size());assertTrue(group.x>=0);assertTrue(group.x<=512);int[] count={0};map.setPhotoTapListener(items->count[0]=items.size());assertTrue(map.tapPhotos(group.x,group.y));assertEquals(1,count[0]);}finally{map.close();}}
 @Test public void wrapAtDateLineShowsSeparatePhotos(){MapView map=new MapView(RuntimeEnvironment.getApplication());map.online=false;try{map.layout(0,0,512,512);map.cx=0;map.cy=128;map.zoom=12;map.setPhotos(photos(photo(1,179.999),photo(2,-179.999)));assertEquals(2,map.photoGroups().size());assertEquals(1,map.photoGroups().get(0).photos.size());}finally{map.close();}}
 @Test public void separateCalloutsRenderWithLeaders()throws Exception{MapView map=new MapView(RuntimeEnvironment.getApplication());map.online=false;try{map.layout(0,0,432,640);map.cx=128;map.cy=128;map.zoom=16;map.setPhotos(photos(photo(3,0),photo(2,0),photo(1,0),photo(4,.003)));Bitmap image=Bitmap.createBitmap(432,640,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(0xff9cabb1);map.drawPhotos(canvas);assertEquals(4,map.photoGroups().size());assertEquals(1,map.photoGroups().get(0).photos.size());java.io.File target=new java.io.File("build/rendered/photo-callouts-017.png");target.getParentFile().mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(target)){assertTrue(image.compress(Bitmap.CompressFormat.PNG,100,out));}}finally{map.close();}}
 @Test public void reorderedInputKeepsIdentityPositions(){Store.Photo a=photo(1,0),b=photo(2,0),c=photo(3,0);ArrayList<PhotoGroups.Group> first=PhotoGroups.spread(photos(c,a,b),new float[]{250,250,250},new float[]{250,250,250},50,500,500),second=PhotoGroups.spread(photos(b,c,a),new float[]{250,250,250},new float[]{250,250,250},50,500,500);assertEquals(3,first.size());for(int i=0;i<3;i++){assertEquals(first.get(i).photos.get(0).id,second.get(i).photos.get(0).id);assertEquals(first.get(i).x,second.get(i).x,0);assertEquals(first.get(i).y,second.get(i).y,0);}}
 @Test public void isolatedCardHasNoLeaderPixels(){MapView map=new MapView(RuntimeEnvironment.getApplication());map.online=false;try{map.layout(0,0,512,512);map.cx=128;map.cy=128;map.zoom=16;map.setPhotos(photos(photo(1,0)));PhotoGroups.Group g=map.photoGroups().get(0);assertEquals(256,g.x,0);assertEquals(256,g.y,0);Bitmap image=Bitmap.createBitmap(512,512,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(0xff9cabb1);map.drawPhotos(canvas);for(int y=30;y<470;y++)for(int x=30;x<470;x++)if(Math.abs(x-256)>25||Math.abs(y-256)>25)assertEquals("No line or anchor outside isolated card",0xff9cabb1,image.getPixel(x,y));}finally{map.close();}}
 android.widget.Button find(android.view.View v,String label){if(v instanceof android.widget.Button&&((android.widget.Button)v).getText().toString().contains(label))return (android.widget.Button)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){android.widget.Button b=find(g.getChildAt(i),label);if(b!=null)return b;}}return null;}
 @Test public void chooserHasDistinctLabelsAndOpensEverySelectedId(){org.robolectric.android.controller.ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();MainActivity activity=controller.get();ArrayList<Store.Photo> ps=photos(photo(3,0),photo(2,0),photo(1,0));for(int i=0;i<ps.size();i++){activity.showPhotos(ps);AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();android.widget.Button item=find(dialog.getWindow().getDecorView(),Language.text(activity,R.string.photo)+ps.get(i).id);assertNotNull(item);item.performClick();Intent opened=Shadows.shadowOf(activity).getNextStartedActivity();assertEquals(PhotoActivity.class.getName(),opened.getComponent().getClassName());assertEquals(ps.get(i).id,opened.getLongExtra("id",-1));}controller.pause().stop().destroy();}
}
